<template>
  <div id="strategyFromDatabank" class="selection">
    <div><input v-model="params.type" value="strategyFromDatabank" type="radio">Strategy from databank</div>
    <div class="data">
        <select :disabled="params.type != 'strategyFromDatabank'" v-model="params.project">
            <option value="">Choose project</option>
        </select>
        <select :disabled="params.type != 'strategyFromDatabank'" v-model="params.databank">
            <option value="">Choose databank</option>
        </select>
        <select :disabled="params.type != 'strategyFromDatabank'" v-model="params.strategies">
            <option value="">Choose strategies</option>
        </select>
    </div>
  </div>
  <div id="projectConfig" class="selection selectionTable">
    <div><input v-model="params.type" value="projectConfigs" type="radio"> Project config(s)</div>
    <div class="data">
        <table class="table">
            <tr>
                <td><input :disabled="params.type != 'projectConfigs'" value="Builder 1" v-model="params.projectConfigs" type="checkbox"></td>
                <td><div class="text">Builder</div></td>
            </tr>
            <tr>
                <td><input :disabled="params.type != 'projectConfigs'" value="Builder 2" v-model="params.projectConfigs" type="checkbox"></td>
                <td><div class="text">Builder</div></td>
            </tr>
            <tr>
                <td><input :disabled="params.type != 'projectConfigs'" value="Builder 3" v-model="params.projectConfigs" type="checkbox"></td>
                <td><div class="text">Builder</div></td>
            </tr>
        </table>
    </div>
  </div>
  <div id="programLogs" class="selection selectionTable">
    <div><input v-model="params.type" value="programLogs" type="radio"> Program log(s)</div>
    <div class="data">
        <table gap="0" class="table">
            <tr>
                <td><input :disabled="params.type != 'programLogs'" value="Builder 1" v-model="params.programLogs" type="checkbox"></td>
                <td><div class="text">Builder</div></td>
            </tr>
            <tr>
                <td><input :disabled="params.type != 'programLogs'" value="Builder 2" v-model="params.programLogs" type="checkbox"></td>
                <td><div class="text">Builder</div></td>
            </tr>
            <tr>
                <td><input :disabled="params.type != 'programLogs'" value="Builder 3" v-model="params.programLogs" type="checkbox"></td>
                <td><div class="text">Builder</div></td>
            </tr>
        </table>
    </div>
  </div>
  <div id="fileOnDisk" class="selection">
    <div><input v-model="params.type" value="fileOnDisk" type="radio"> File on disk</div>
    <div class="data">
        <span @click="browse" class="browse">Browse</span>
    </div>
  </div>
  <div align="right" id="buttons" class="selection">
    <span @click="changePage('openTicket')" class="close">Close</span>
    <button @click="save()" class="save">Save</button>
  </div>
</template>

<script>
export default {
  name: 'AddFile',
  props: {
    msg: String
  },
  methods:{
    browse(){
        console.log(this.params)
        alert("browse")
    },
    changePage(page){
      this.$emit('changePage', page)
    },
    save(){
        this.changePage('openTicket')
    }
  },
  data(){
    return {
      params: {
        type: "strategyFromDatabank",
        project: "",
        databank: "",
        strategies: "",
        projectConfigs: [],
        programLogs: [],
        file: ""
      }
    }
  }
}
</script>

<style scoped>
    .selection{
        margin-bottom: 15px;
    }
    #strategyFromDatabank .data{
        margin-top: 15px;
        display: grid;
        grid-template-columns: 25% 25% 25%;
    }
    #strategyFromDatabank .data select{
        margin-right: 15px;
        padding: 6px 15px 6px 6px;
    }
    .selectionTable .data{
        margin-top: 15px;
        max-height: 25vh;
    }
    .selectionTable .table{
        display: inline-block;
        border-collapse: collapse;
    }
    .selectionTable .table tr,td{
        border: 1px solid grey;
        border-collapse: collapse;
    }
    .selectionTable .table .text{
        padding: 3px 90px 3px 9px;
    }
    #fileOnDisk .data{
        margin-top: 15px;
    }
    #fileOnDisk .browse{
        color: blue;
        cursor: pointer;
    }
    #buttons{
        border-top: 1px solid grey;
        padding-top: 15px;
    }
    #buttons .close{
        cursor: pointer
    }
    #buttons .save{
        background: rgb(0, 158, 231);
        padding: 6px 15px 6px 15px;
        color: white;
        border: none;
        margin-left: 9px;
        cursor: pointer;
    }
</style>
